(() => {
  const rows = QueryLabDeptAsset1.data || [];

  const prettyName = (name) => {
    return String(name || "")
      .replace(/_/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  };

  // Group by Lab → Location
  const byLab = {};

  rows.forEach(r => {
    const labKey = String(r.Lab || "Unknown Lab");
    const locKey = String(r.Location || "Unassigned Location");

    if (!byLab[labKey]) byLab[labKey] = {};
    if (!byLab[labKey][locKey]) byLab[labKey][locKey] = [];

    byLab[labKey][locKey].push({
      label: prettyName(r.HardwareName),
      value: `hw:${r.ID}`
    });
  });

  // Build TreeSelect structure
  return Object.entries(byLab).map(([lab, locs]) => ({
    label: `Lab ${lab}`,
    value: `lab:${lab}`,
    children: Object.entries(locs).map(([loc, items]) => ({
      label: prettyName(loc),
      value: `loc:${lab}:${loc}`,
      children: items.sort((a, b) => a.label.localeCompare(b.label))
    }))
  }));
})()
}}
